def get_synonym(word: str, mode: str = "professional") -> Optional[str]:
    w_lower = word.lower()
    if w_lower in SYNONYM_MAP:
        cand = SYNONYM_MAP[w_lower].get(mode.lower())
        if cand:
            if word.isupper():
                return cand.upper()
            elif word[0].isupper():
                return cand.capitalize()
            return cand
    return None
